export function getComponentLabel(char: string, rawLabel?: string): string {
  if (KANJI_ETYMOLOGY_NAMES[char]) return KANJI_ETYMOLOGY_NAMES[char]
  if (rawLabel) {
    const clean = rawLabel.trim()
    return clean.charAt(0).toUpperCase() + clean.slice(1).toLowerCase()
  }
  return char
}
